export const supportedLanguages=['zh-CN','en-US'];
export function translate(value,language='zh-CN'){
 const text=String(value??'');
 if(language!=='en-US')return text;
 const exact=en[text]??tableEn[text]??uiEn[text]??toastEn[text]??stateEn[text];if(exact)return exact;
 let match=text.match(/^(\d+(?:\.\d+)?) 秒$/);if(match)return `${match[1]} sec`;
 match=text.match(/^第 (\d+) 次$/);if(match)return `Run ${match[1]}`;
 match=text.match(/^(\d[\d,]*) 个样本$/);if(match)return `${match[1]} samples`;
 match=text.match(/^(\d[\d,]*) 项本地证据$/);if(match)return `${match[1]} local evidence items`;
 match=text.match(/^(\d[\d,]*) 项(?: · 单个文件最多 ([\d.]+ MiB))?$/);if(match)return match[2]?`${match[1]} items · ${match[2]} per file`:`${match[1]} items`;
 match=text.match(/^(\d[\d,]*) 份记录$/);if(match)return `${match[1]} sessions`;
 match=text.match(/^(\d[\d,]*) 节点$/);if(match)return `${match[1]} nodes`;
 match=text.match(/^(\d[\d,]*) 组 · (\d[\d,]*) 个超预算帧$/);if(match)return `${match[1]} groups · ${match[2]} over-budget frames`;
 match=text.match(/^起点 (.+) · 显示区间 (.+)$/);if(match)return `Start ${match[1]} · displayed range ${match[2]}`;
 match=text.match(/^记录目录：(.*?)。演示记录保留演示来源；导入记录保留文件声明的来源元数据。可在详情窗口导出 JSON。$/);if(match)return `Record directory: ${match[1]}. Demo records retain their demo source; imported records retain source metadata declared in their files. Export JSON from the details dialog.`;
 match=text.match(/^从已保存的 Benchmark 运行中选择；(\d+) 份可用$/);if(match)return `Choose from saved Benchmark runs; ${match[1]} available`;
 if(text.startsWith('Event: ')&&text.includes('Current：全部时间'))return text.replace('Current：全部时间','Current: all time');
 const networkLead='展示当前筛选中开始时间和总耗时均可用的最早 200 条请求；重叠仅表示记录的时间重合，不证明因果关系。';if(text.startsWith(networkLead))return `${en[networkLead]||networkLead} ${text.slice(networkLead.length).replace('，','.')}`;
 if(text.startsWith('当前快照：')&&text.includes('Baseline snapshot：'))return text.replace('当前快照：','Current snapshot:').replace('Baseline snapshot：','Baseline snapshot:');
 if(text.startsWith('P50 ')&&text.includes('平台 Janky frames 计数：'))return text.replace('平台 Janky frames 计数：不可用（可能与缓冲区范围不同）','Platform Janky frames: unavailable (may use a different buffer range)');
 return exact??text;
}

const originalTextByNode=new WeakMap();
const originalAttributesByElement=new WeakMap();
export function localizeTextNodes(root,language='zh-CN'){
 const walker=root.ownerDocument.createTreeWalker(root,4);
 while(walker.nextNode()){
  const node=walker.currentNode,parent=node.parentElement;
  if(!parent||parent.closest('pre,code,textarea,input,td,.tree,.sample-screen,.phone-preview,[data-source-file],[data-source-match],[data-user-content]'))continue;
 if(!parent.matches('h1,h2,h3,h4,a,button,label,th,dt,option,small,strong,p,.hint,.subtle,.tag,.eyebrow,.metric-note,.section-heading span,.footer-tagline,.empty,.empty-chart'))continue;
  const original=originalTextByNode.get(node)??node.nodeValue;
  originalTextByNode.set(node,original);
  const trimmed=original.trim(),translated=translate(trimmed,language);
  if(trimmed&&node.nodeValue!==original.replace(trimmed,translated))node.nodeValue=original.replace(trimmed,translated);
 }
 for(const element of root.querySelectorAll?.('[aria-label], [placeholder]')||[]){
  if(element.closest('[data-user-content]'))continue;
  let originals=originalAttributesByElement.get(element);if(!originals){originals={};originalAttributesByElement.set(element,originals);}
  for(const attribute of ['aria-label','placeholder'])if(element.hasAttribute(attribute)){if(!(attribute in originals))originals[attribute]=element.getAttribute(attribute);element.setAttribute(attribute,translate(originals[attribute],language));}
 }
}
